{
  "name": "超声波测距传感器",
  "name_en": "Ultrasonic Distance Sensor",
  "manufacturer": "",
  "description": "一种基于 HC-SR04 一类模块的超声波距离传感器，通过发射超声脉冲并测量回波返回时间来估算目标距离。常用于实验室与教学场景中的接近检测、障碍物探测、液位估计、位置触发和机器人避障等应用，通常通过 GPIO 的触发与回波引脚连接控制。",
  "description_en": "An ultrasonic distance sensor of the HC-SR04 class that estimates target distance by emitting ultrasonic pulses and timing the returning echo. It is commonly used in lab and teaching setups for proximity sensing, obstacle detection, level estimation, position-based triggering, and basic robotics, typically via GPIO trigger and echo connections.",
  "tag_hints": [
    "HC-SR04",
    "ultrasonic ranging",
    "distance measurement",
    "proximity sensing",
    "obstacle detection",
    "GPIO sensor"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭设备并释放 GPIO 引脚。",
      "description_en": "Close the device and release its GPIO pins."
    },
    {
      "action_name": "auto-max_distance",
      "description": "获取/设置最大测量距离。",
      "description_en": "Get/set the maximum measurable distance."
    },
    {
      "action_name": "auto-threshold_distance",
      "description": "获取/设置距离阈值。",
      "description_en": "Get/set the distance threshold."
    },
    {
      "action_name": "auto-distance",
      "description": "获取当前测得的距离。",
      "description_en": "Get the current measured distance."
    },
    {
      "action_name": "auto-value",
      "description": "获取归一化测距值。",
      "description_en": "Get the normalized distance value."
    },
    {
      "action_name": "auto-trigger",
      "description": "获取触发引脚。",
      "description_en": "Get the trigger pin."
    },
    {
      "action_name": "auto-echo",
      "description": "获取回波引脚。",
      "description_en": "Get the echo pin."
    },
    {
      "action_name": "auto-in_range",
      "description": "获取是否处于设定距离范围内。",
      "description_en": "Get whether the sensor is within the configured range."
    },
    {
      "action_name": "auto-pull_up",
      "description": "获取输入引脚的上拉配置。",
      "description_en": "Get the pull-up configuration of the input pin."
    },
    {
      "action_name": "auto-queue_len",
      "description": "获取用于平滑测量的队列长度。",
      "description_en": "Get the queue length used for smoothing measurements."
    },
    {
      "action_name": "auto-partial",
      "description": "获取队列未填满时是否允许返回部分结果。",
      "description_en": "Get whether partial results are allowed before the queue is full."
    },
    {
      "action_name": "auto-threshold",
      "description": "获取/设置激活阈值。",
      "description_en": "Get/set the activation threshold."
    },
    {
      "action_name": "auto-is_active",
      "description": "获取传感器是否处于激活状态。",
      "description_en": "Get whether the sensor is active."
    }
  ]
}

